package pe.pisacoma.iglesia.data

import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** The bundled content generated by tools/sync-content.mjs is in the source tree. */
class AssetsPresentTest {
    private fun asset(path: String) = File("src/main/assets/$path")

    private fun assertAtLeast(path: String, bytes: Long) {
        val f = asset(path)
        assertTrue("$path missing — run tools/sync-content.mjs", f.isFile)
        assertTrue("$path is only ${f.length()} bytes", f.length() >= bytes)
    }

    @Test fun spanishHymnal() = assertAtLeast("data/himnario-es.json", 500_000)
    @Test fun portugueseHymnals() { assertAtLeast("data/himnario-pt.json", 300_000); assertAtLeast("data/himnario-pt-novo.json", 300_000) }
    @Test fun bibleFirstBook() = assertAtLeast("data/biblia/1.json", 100_000)
    @Test fun bibleHasSixtySixBooks() = assertTrue(asset("data/biblia").listFiles()!!.count { it.name.endsWith(".json") } == 66)
    @Test fun egwBook() = assertAtLeast("data/egw/cc.json", 100_000)
    @Test fun egwCatalogueHas25Books() = assertTrue(asset("data/egw").listFiles()!!.count { it.name.endsWith(".json") } == 25)
    @Test fun quarterly() = assertAtLeast("data/escuela-sabatica.json", 300_000)
    @Test fun searchIndex() = assertAtLeast("data/search-index.json", 100_000)
    @Test fun quizzes() = assertAtLeast("data/quizzes.json", 10_000)
    @Test fun church() = assertAtLeast("data/church.json", 1_000)
    @Test fun homeLottie() = assertAtLeast("home/lottie/inicio-portrait.json", 2_000)
    @Test fun homePoster() = assertAtLeast("home/inicio-portrait.jpg", 20_000)
    @Test fun fonts() { for (f in listOf("fraunces", "fraunces_italic", "inter", "dm_sans")) assertTrue(File("src/main/res/font/$f.ttf").length() > 30_000) }
}
